function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0 }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      style={{
        transform: visible ? "none" : "translateY(18px)",
        opacity: visible ? 1 : 0,
        transition: `all 0.6s cubic-bezier(.2,.7,.3,1) ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

function Tag({ children, tone = "accent" }) {
  const bg = tone === "accent" ? COLORS.accentSoft : COLORS.tealSoft;
  const fg = tone === "accent" ? COLORS.accent : COLORS.teal;
  return (
    <span
      style={{
        fontFamily: FONT_MONO,
        fontSize: "11px",
        letterSpacing: "0.03em",
        padding: "4px 10px",
        borderRadius: "999px",
        background: bg,
        color: fg,
        marginRight: "6px",
        marginBottom: "6px",
        display: "inline-block",
      }}
    >
      {children}
    </span>
  );
}

